apiVersion: v1
kind: ConfigMap
metadata:
  name: server-config
  namespace: server
data:
  NODE_ENV: "development"
  PORT: "3000"
  DATABASE_URL: "REDACTED"
  KAFKA_BROKER_URL: "redpanda:29092"
  EMAIL_HOST: "mailhog"
  EMAIL_PORT: "1025"

---
apiVersion: v1
kind: ConfigMap
metadata:
  name: nginx-config
  namespace: server
data:
  default.conf: |
    upstream auth_upstream {
      server auth-service:3000;
    }

    upstream wallet_upstream {
      server wallet-service:3000;
    }

    upstream user_upstream {
      server user-service:3000;
    }

    server {
      listen 80;
      server_name _;

      location = /api/auth {
        return 301 /api/auth/;
      }

      location ^~ /api/auth/ {
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_pass http://auth_upstream;
      }

      location = /api/wallet {
        return 301 /api/wallet/;
      }

      location ^~ /api/wallet/ {
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_pass http://wallet_upstream;
      }

      location = /api/user {
        return 301 /api/user/;
      }

      location ^~ /api/user/ {
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_pass http://user_upstream;
      }
    }

