  adjustBalance(
    accountNumber: TBankAccountNumber,
    amount: number,
  ): Promise<number> {
    return tryCatch({
      ctx: async () => {
        const accounts = await this.client.lookupAccounts([accountNumber]);
        const tbAccount = accounts[0];

        if (!tbAccount) throw new Error("Account not found");

        const credits = Number(tbAccount.credits_posted);
        const debits = Number(tbAccount.debits_posted);
        const currentBalance = credits - debits;
        const newBalance = currentBalance + amount;

        if (newBalance < 0) {
          throw new Error("Insufficient funds");
        }

        const transferAmount = Math.abs(amount);

        const transferResults = await this.client.createTransfers([
          {
            id: TB.id(),
            debit_account_id: amount < 0 ? accountNumber : accountNumber,
            credit_account_id: amount > 0 ? accountNumber : accountNumber,
            ledger: WALLET_LEDGER_CODE,
            code: CURRENCY_CODE.INR,
            flags:
              amount > 0
                ? TB.TransferFlags.post_pending_transfer
                : TB.TransferFlags.post_pending_transfer,
            amount: BigInt(transferAmount),
            user_data_128: 0n,
            user_data_64: 0n,
            user_data_32: 0,
            pending_id: 0n,
            timeout: 0,
          },
        ]);

        if (transferResults.length !== 1 || !transferResults[0]) {
          throw new Error("Failed to create transfer in TigerBeetle");
        }

        const transferResult = transferResults[0];

        if (transferResult.result !== TB.TransferResult.success) {
          throw new Error(
            `Transfer failed: ${TB.TransferResult[transferResult.result]}`,
          );
        }

        const updatedAccounts = await this.client.lookupAccounts([accountNumber]);
        const updated = updatedAccounts[0];
        if (!updated) throw new Error("Account not found after balance adjustment");

        return Number(updated.credits_posted) - Number(updated.debits_posted);
      },
      errorMessage: "FAILED_TO_ADJUST_BALANCE",
    });
  }

  checkBalance(accountNumber: TBankAccountNumber): Promise<IAccountDTO> {
    return tryCatch({
      ctx: async () => {
        const account = await this.findByAccountNumber(accountNumber);
        if (!account) throw new Error("Account not found");
        return account;
      },
      errorMessage: "FAILED_TO_CHECK_BALANCE",
    });
  }
}

