```rust
use anyhow::Result;
use tigerbeetle_node::*;

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    tracing_subscriber::fmt::init();

    // Connect to TigerBeetle
    let cluster_id: u128 = 1;
    let replica_addresses: Vec<String> = vec!["127.0.0.1:4343".into()];

    let client = Client::new(cluster_id, replica_addresses)?;

    tracing::info!("Connected to TigerBeetle");

    // Create a test account
    let account = Account {
        id: 1,
        debits_must_not_exceed_credits: true,
        credits_must_not_exceed_debits: false,
        ..Default::default()
    };

    let results = client.create_accounts(&[account])?;
    tracing::info!("Account created: {:?}", results);

    // Lookup the account
    let accounts = client.lookup_accounts(&[1])?;
    if let Some(acc) = accounts.first() {
        tracing::info!(
            "Account 1: debits_posted={}, credits_posted={}",
            acc.debits_posted,
            acc.credits_posted
        );
    }

    Ok(())
}
```

### Run It

```bash
# Make sure TigerBeetle is running (docker compose up tigerbeetle)
cargo run
```

You should see:
```
