## Phase 2: Transfer Engine

Now let's build the HTTP server.

### src/main.rs

```rust
use anyhow::Result;
use axum::{
    extract::State,
    routing::post,
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tigerbeetle_node::*;
use uuid::Uuid;

// Shared state
struct AppState {
    client: Arc<Client>,
}

// Request/Response types
#[derive(Deserialize)]
struct CreateTransferRequest {
    from_wallet: u128,
    to_wallet: u128,
    amount: u128,
}

#[derive(Serialize)]
struct CreateTransferResponse {
    id: String,
    status: String,
    amount: u128,
}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt::init();

    // Connect to TigerBeetle
    let cluster_id: u128 = 1;
    let replica_addresses: Vec<String> = vec!["127.0.0.1:4343".into()];
    let client = Client::new(cluster_id, replica_addresses)?;

    let state = Arc::new(AppState {
        client: Arc::new(client),
    });

    // Build router
    let app = Router::new()
        .route("/transfers", post(create_transfer))
        .route("/health", axum::routing::get(health))
        .with_state(state);

    // Start server
    let listener = tokio::net::TcpListener::bind("0.0.0.0:3001").await?;
    tracing::info!("Transfer service listening on :3001");
    axum::serve(listener, app).await?;

    Ok(())
}

async fn health() -> &'static str {
    "OK"
}

async fn create_transfer(
    State(state): State<Arc<AppState>>,
    Json(request): Json<CreateTransferRequest>,
) -> Result<Json<CreateTransferResponse>, Json<ErrorResponse>> {
    let transfer_id = Uuid::new_v4().as_u128();

    // Execute transfer in TigerBeetle
    let transfer = Transfer {
        id: transfer_id,
        debit_account_id: request.from_wallet,
        credit_account_id: request.to_wallet,
        amount: request.amount,
        ..Default::default()
    };

    let results = state.client.create_transfers(&[transfer])
        .map_err(|e| Json(ErrorResponse { error: e.to_string() }))?;

    match results.first() {
        Some(result) if result.result == TransferStatus::Created => {
            Ok(Json(CreateTransferResponse {
                id: transfer_id.to_string(),
                status: "success".to_string(),
                amount: request.amount,
            }))
        }
        Some(result) => {
            Err(Json(ErrorResponse {
                error: format!("Transfer failed: {:?}", result.result),
            }))
        }
        None => {
            Err(Json(ErrorResponse {
                error: "No result returned".to_string(),
            }))
        }
    }
}
```

### Test It

```bash
# Terminal 1: Start TigerBeetle
docker compose up tigerbeetle

# Terminal 2: Start Rust service
cargo run

# Terminal 3: Test
curl -X POST http://localhost:3001/transfers \
  -H "Content-Type: application/json" \
  -d '{"from_wallet": 1, "to_wallet": 2, "amount": 100}'
```

---

## What You'll Learn

By the end of Phase 1-2, you'll know:

| Rust Concept | Where You'll See It |
|-------------|-------------------|
| Ownership & borrowing | `Arc<AppState>` for shared state |
| Error handling | `Result<T, E>`, `?` operator, `thiserror` |
| Async/await | `#[tokio::main]`, `.await` |
| Pattern matching | `match results.first()` |
| Structs & impls | `AppState`, `CreateTransferRequest` |
| Traits | `Serialize`, `Deserialize` |
| Crates | `axum`, `tokio`, `serde`, `tracing` |

---

## The Fun Part

This is a hobby project, so let's make it fun:

1. **Benchmark it** — Compare Rust vs TypeScript transfer speed
2. **Add metrics** — Track transfers/sec, latency, errors
3. **Make it pretty** — Nice terminal output with colors
4. **Document it** — Write a README that explains your Rust journey

