mod config;
mod error;
mod handlers;
mod models;
mod tigerbeetle;

use axum::{routing::get, Router};
use std::sync::Arc;
use tower_http::trace::TraceLayer;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt;

use crate::config::Config;
use crate::tigerbeetle::TigerBeetleClient;

#[derive(Clone)]
pub struct AppState {
    pub tigerbeetle: Arc<TigerBeetleClient>,
    pub config: Arc<Config>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Load .env if present
    let _ = dotenvy::dotenv();

    // Initialize tracing
    tracing_subscriber::registry()
        .with(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "transfer_service=debug,tower_http=debug".into()),
        )
        .with(tracing_subscriber::fmt::layer())
        .init();

    // Load config
    let config = Arc::new(Config::from_env()?);
    tracing::info!("Configuration loaded");

    // Connect to TigerBeetle
    let tb_client = Arc::new(TigerBeetleClient::new(&config).await?);
    tracing::info!("Connected to TigerBeetle at {}:{}", config.tb_host, config.tb_port);

    // Create shared state
    let state = AppState {
        tigerbeetle: tb_client,
        config,
    };

    // Build router
    let app = Router::new()
        .route("/health", get(handlers::health))
        .route("/accounts", get(handlers::list_accounts).post(handlers::create_account))
        .route("/accounts/:account_id", get(handlers::get_account))
        .route("/accounts/:account_id/balance", get(handlers::get_balance))
        .route("/transfers", get(handlers::list_transfers).post(handlers::create_transfer))
        .route("/transfers/:transfer_id", get(handlers::get_transfer))
        .layer(TraceLayer::new_for_http())
        .with_state(state);

    // Start server
    let addr = format!("0.0.0.0:{}", std::env::var("PORT").unwrap_or_else(|_| "3001".into()));
    let listener = tokio::net::TcpListener::bind(&addr).await?;
    tracing::info!("Transfer service listening on {}", addr);

    axum::serve(listener, app).await?;

    Ok(())
}

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde_json::json;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum AppError {
    #[error("TigerBeetle error: {0}")]
    TigerBeetle(String),

    #[error("Account not found: {0}")]
    AccountNotFound(u128),

    #[error("Insufficient funds: available {available}, requested {requested}")]
    InsufficientFunds { available: u128, requested: u128 },

    #[error("Invalid request: {0}")]
    BadRequest(String),

    #[error("Internal error: {0}")]
    Internal(String),
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, message) = match &self {
            AppError::TigerBeetle(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.to_string()),
            AppError::AccountNotFound(_) => (StatusCode::NOT_FOUND, self.to_string()),
            AppError::InsufficientFunds { .. } => (StatusCode::BAD_REQUEST, self.to_string()),
            AppError::BadRequest(_) => (StatusCode::BAD_REQUEST, self.to_string()),
            AppError::Internal(_) => (StatusCode::INTERNAL_SERVER_ERROR, self.to_string()),
        };

        let body = Json(json!({
            "error": message,
            "status": status.as_u16(),
        }));

        (status, body).into_response()
    }
}

use anyhow::{Context, Result};
use enfipy_tigerbeetle::{Account, Client, Transfer};
use std::str::FromStr;

use crate::config::Config;

pub struct TigerBeetleClient {
    client: Client,
    pub ledger_code: u32,
    pub currency_code: u16,
}

impl TigerBeetleClient {
    pub async fn new(config: &Config) -> Result<Self> {
        let address = config.tb_address();

        // Resolve hostname to IP if needed
        let resolved_addr = if is_ip(&address.split(':').next().unwrap_or("")) {
            address.clone()
        } else {
            let host = address.split(':').next().unwrap_or("");
            let port = address.split(':').last().unwrap_or("4343");
            let ip = resolve_host(host).await.unwrap_or_else(|_| host.to_string());
            format!("{}:{}", ip, port)
        };

        tracing::info!("Connecting to TigerBeetle at {}", resolved_addr);

        let client = Client::new(config.tb_cluster_id, resolved_addr.as_bytes())
            .context("Failed to create TigerBeetle client")?;

        Ok(Self {
            client,
            ledger_code: config.ledger_code,
            currency_code: config.currency_code,
        })
    }

    pub async fn create_account(
        &self,
        id: u128,
        ledger: Option<u32>,
        code: Option<u16>,
        user_data_128: Option<u128>,
        user_data_64: Option<u64>,
        user_data_32: Option<u32>,
    ) -> Result<Account> {
        let account = Account::new(id, ledger.unwrap_or(self.ledger_code), code.unwrap_or(self.currency_code))
            .with_user_data_128(user_data_128.unwrap_or(0))
            .with_user_data_64(user_data_64.unwrap_or(0))
            .with_user_data_32(user_data_32.unwrap_or(0));

        self.client
            .create_accounts(vec![account])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to create account: {:?}", e))?;

        // Lookup to get the created account
        let accounts = self.client
            .lookup_accounts(vec![id])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to lookup account: {:?}", e))?;

        accounts
            .into_iter()
            .next()
            .ok_or_else(|| anyhow::anyhow!("Account not found after creation"))
    }

    pub async fn get_account(&self, id: u128) -> Result<Option<Account>> {
        let accounts = self.client
            .lookup_accounts(vec![id])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to lookup account: {:?}", e))?;

        Ok(accounts.into_iter().next())
    }

    pub async fn create_transfer(
        &self,
        req: crate::models::CreateTransferRequest,
    ) -> Result<Transfer> {
        let transfer = Transfer::new(
            req.id.unwrap_or_else(|| fastrand::u128(..)),
            req.debit_account_id,
            req.credit_account_id,
            req.amount,
            req.ledger.unwrap_or(self.ledger_code),
            req.code.unwrap_or(self.currency_code),
        )
        .with_user_data_128(req.user_data_128.unwrap_or(0))
        .with_user_data_64(req.user_data_64.unwrap_or(0))
        .with_user_data_32(req.user_data_32.unwrap_or(0));

        // Set flags if provided
        let transfer = if let Some(flags) = req.flags {
            transfer.with_flags(flags)
        } else {
            transfer
        };

        self.client
            .create_transfers(vec![transfer])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to create transfer: {:?}", e))?;

        // Lookup the transfer
        let transfer_id = req.id.unwrap_or_else(|| fastrand::u128(..));
        let transfers = self.client
            .lookup_transfers(vec![transfer_id])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to lookup transfer: {:?}", e))?;

        transfers
            .into_iter()
            .next()
            .ok_or_else(|| anyhow::anyhow!("Transfer not found after creation"))
    }

    pub async fn get_transfer(&self, id: u128) -> Result<Option<Transfer>> {
        let transfers = self.client
            .lookup_transfers(vec![id])
            .await
            .map_err(|e| anyhow::anyhow!("Failed to lookup transfer: {:?}", e))?;

        Ok(transfers.into_iter().next())
    }
}

fn is_ip(host: &str) -> bool {
    std::net::IpAddr::from_str(host).is_ok()
}

async fn resolve_host(host: &str) -> Result<String> {
    use tokio::net::lookup_host;

    let addr = format!("{}:0", host);
    let resolved = lookup_host(&addr)
        .await
        .context(format!("Failed to resolve host: {}", host))?
        .next()
        .ok_or_else(|| anyhow::anyhow!("No addresses found for {}", host))?;

    Ok(resolved.ip().to_string())
}

use axum::{
    extract::{Path, State},
    Json,
};
use serde_json::{json, Value};

use crate::error::AppError;
use crate::models::*;
use crate::AppState;

// ── Health ───────────────────────────────────────────
pub async fn health() -> Json<Value> {
    Json(json!({
        "status": "ok",
        "service": "transfer-service",
    }))
}

// ── Account Handlers ─────────────────────────────────
pub async fn create_account(
    State(state): State<AppState>,
    Json(req): Json<CreateAccountRequest>,
) -> Result<Json<Value>, AppError> {
    let id = req.id.unwrap_or_else(|| fastrand::u128(..));

    let account = state
        .tigerbeetle
        .create_account(
            id,
            req.ledger,
            req.code,
            req.user_data_128,
            req.user_data_64,
            req.user_data_32,
        )
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?;

    Ok(Json(json!({
        "id": account.id(),
        "ledger": account.ledger(),
        "code": account.code(),
        "debits_pending": account.debits_pending(),
        "debits_posted": account.debits_posted(),
        "credits_pending": account.credits_pending(),
        "credits_posted": account.credits_posted(),
        "user_data_128": account.user_data_128(),
        "user_data_64": account.user_data_64(),
        "user_data_32": account.user_data_32(),
    })))
}

pub async fn get_account(
    State(state): State<AppState>,
    Path(account_id): Path<u128>,
) -> Result<Json<Value>, AppError> {
    let account = state
        .tigerbeetle
        .get_account(account_id)
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?
        .ok_or(AppError::AccountNotFound(account_id))?;

    Ok(Json(json!({
        "id": account.id(),
        "ledger": account.ledger(),
        "code": account.code(),
        "debits_pending": account.debits_pending(),
        "debits_posted": account.debits_posted(),
        "credits_pending": account.credits_pending(),
        "credits_posted": account.credits_posted(),
        "user_data_128": account.user_data_128(),
        "user_data_64": account.user_data_64(),
        "user_data_32": account.user_data_32(),
    })))
}

pub async fn get_balance(
    State(state): State<AppState>,
    Path(account_id): Path<u128>,
) -> Result<Json<Value>, AppError> {
    let account = state
        .tigerbeetle
        .get_account(account_id)
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?
        .ok_or(AppError::AccountNotFound(account_id))?;

    let balance = account.credits_posted() as i128 - account.debits_posted() as i128;

    Ok(Json(json!({
        "account_id": account.id(),
        "balance": balance,
        "debits_pending": account.debits_pending(),
        "debits_posted": account.debits_posted(),
        "credits_pending": account.credits_pending(),
        "credits_posted": account.credits_posted(),
    })))
}

pub async fn list_accounts(
    State(_state): State<AppState>,
) -> Result<Json<Value>, AppError> {
    // TigerBeetle doesn't have a list-all endpoint, so we return empty for now
    // In production, you'd maintain an index in Postgres
    Ok(Json(json!({
        "accounts": [],
        "message": "Use GET /accounts/:id to lookup specific accounts"
    })))
}

// ── Transfer Handlers ────────────────────────────────
pub async fn create_transfer(
    State(state): State<AppState>,
    Json(req): Json<CreateTransferRequest>,
) -> Result<Json<Value>, AppError> {
    // Validate
    if req.amount == 0 {
        return Err(AppError::BadRequest("Amount must be greater than 0".into()));
    }

    if req.debit_account_id == req.credit_account_id {
        return Err(AppError::BadRequest("Cannot transfer to same account".into()));
    }

    // Check source account has sufficient funds
    let source_account = state
        .tigerbeetle
        .get_account(req.debit_account_id)
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?
        .ok_or(AppError::AccountNotFound(req.debit_account_id))?;

    let available = source_account.credits_posted() as i128 - source_account.debits_posted() as i128;
    if available < req.amount as i128 {
        return Err(AppError::InsufficientFunds {
            available: available as u128,
            requested: req.amount,
        });
    }

    // Execute transfer
    let transfer = state
        .tigerbeetle
        .create_transfer(req)
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?;

    Ok(Json(json!({
        "id": transfer.id(),
        "debit_account_id": transfer.debit_account_id(),
        "credit_account_id": transfer.credit_account_id(),
        "amount": transfer.amount(),
        "ledger": transfer.ledger(),
        "code": transfer.code(),
        "pending_id": transfer.pending_id(),
        "user_data_128": transfer.user_data_128(),
        "user_data_64": transfer.user_data_64(),
        "user_data_32": transfer.user_data_32(),
    })))
}

pub async fn get_transfer(
    State(state): State<AppState>,
    Path(transfer_id): Path<u128>,
) -> Result<Json<Value>, AppError> {
    let transfer = state
        .tigerbeetle
        .get_transfer(transfer_id)
        .await
        .map_err(|e| AppError::TigerBeetle(e.to_string()))?
        .ok_or(AppError::AccountNotFound(transfer_id))?; // Reusing error for now

    Ok(Json(json!({
        "id": transfer.id(),
        "debit_account_id": transfer.debit_account_id(),
        "credit_account_id": transfer.credit_account_id(),
        "amount": transfer.amount(),
        "ledger": transfer.ledger(),
        "code": transfer.code(),
        "pending_id": transfer.pending_id(),
        "user_data_128": transfer.user_data_128(),
        "user_data_64": transfer.user_data_64(),
        "user_data_32": transfer.user_data_32(),
    })))
}

pub async fn list_transfers(
    State(_state): State<AppState>,
) -> Result<Json<Value>, AppError> {
    Ok(Json(json!({
        "transfers": [],
        "message": "Use GET /transfers/:id to lookup specific transfers"
    })))
}

