pub async fn create_account(
    State(state): State<AppState>,
    Json(req): Json<CreateAccountRequest>,
) -> Result<Json<Value>, AppError> {
    let id = req.id.unwrap_or_else(|| fastrand::u128(..));

    let account = state
        .tigerbeetle
        .create_account(
            id,
            Some(req.ledger),
            Some(req.code),
            req.user_data_128,
            req.user_data_64,
            req.user_data_32,
        )
        .await
        .map_err(|e: anyhow::Error| AppError::TigerBeetle(e.to_string()))?;

    Ok(Json(json!({
        "id": account.id,
        "ledger": account.ledger,
        "code": account.code,
        "debits_pending": account.debits_pending,
        "debits_posted": account.debits_posted,
        "credits_pending": account.credits_pending,
        "credits_posted": account.credits_posted,
        "user_data_128": account.user_data_128,
        "user_data_64": account.user_data_64,
        "user_data_32": account.user_data_32,
    })))
}

