import type { TBankAccountNumber, TUserId } from "@/types";

const TRANSFER_SERVICE_URL = process.env.TRANSFER_SERVICE_URL ?? "http://localhost:3001";

export interface TBCreateAccountRequest {
  id?: string;
  ledger: number;
  code: number;
  user_data_128?: string;
  user_data_64?: number;
  user_data_32?: number;
}

export interface TBCreateAccountResponse {
  id: string;
  ledger: number;
  code: number;
  debits_pending: string;
  debits_posted: string;
  credits_pending: string;
  credits_posted: string;
  user_data_128: string;
  user_data_64: number;
  user_data_32: number;
}

export interface TBCreateTransferRequest {
  id?: string;
  debit_account_id: string;
  credit_account_id: string;
  amount: string;
  ledger?: number;
  code?: number;
  user_data_128?: string;
  user_data_64?: number;
  user_data_32?: number;
  flags?: number;
}

export interface TBCreateTransferResponse {
  id: string;
  debit_account_id: string;
  credit_account_id: string;
  amount: string;
  ledger: number;
  code: number;
  pending_id: string;
  user_data_128: string;
  user_data_64: number;
  user_data_32: number;
}

export interface TBGetBalanceResponse {
  account_id: string;
  balance: string;
  debits_pending: string;
  debits_posted: string;
  credits_pending: string;
  credits_posted: string;
}

let _connected = false;
let _error: string | null = null;

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const url = `${TRANSFER_SERVICE_URL}${path}`;
  const res = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options?.headers,
    },
  });

  if (!res.ok) {
    const body = await res.json().catch(() => null) as { error?: string } | null;
    throw new Error(`Transfer service error (${res.status}): ${body?.error ?? res.statusText}`);
  }

  return res.json() as Promise<T>;
}

export async function healthCheck(): Promise<boolean> {
  try {
    const res = await request<{ status: string }>("/health");
    _connected = res.status === "ok";
    _error = null;
    return _connected;
  } catch (err: unknown) {
    _connected = false;
    _error = err instanceof Error ? err.message : String(err);
    return false;
  }
}

export async function createAccount(req: TBCreateAccountRequest): Promise<TBCreateAccountResponse> {
  return request<TBCreateAccountResponse>("/accounts", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export async function getAccount(id: string): Promise<TBCreateAccountResponse | null> {
  try {
    return await request<TBCreateAccountResponse>(`/accounts/${id}`);
  } catch {
    return null;
  }
}

export async function getBalance(id: string): Promise<TBGetBalanceResponse | null> {
  try {
    return await request<TBGetBalanceResponse>(`/accounts/${id}/balance`);
  } catch {
    return null;
  }
}

export async function createTransfer(req: TBCreateTransferRequest): Promise<TBCreateTransferResponse> {
  return request<TBCreateTransferResponse>("/transfers", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export async function getTransfer(id: string): Promise<TBCreateTransferResponse | null> {
  try {
    return await request<TBCreateTransferResponse>(`/transfers/${id}`);
  } catch {
    return null;
  }
}

export const TransferServiceClient = {
  get connected() { return _connected; },
  get error() { return _error; },
  healthCheck,
  createAccount,
  getAccount,
  getBalance,
  createTransfer,
  getTransfer,
};

import {
  TransferServiceClient,
  type TBCreateAccountRequest,
  type TBCreateAccountResponse,
  type TBCreateTransferRequest,
  type TBCreateTransferResponse,
} from "@/lib/transfer-service/client";
import {
  AccountFlags as _AccountFlags,
  CreateAccountStatus as _CreateAccountStatus,
  CreateTransferStatus as _CreateTransferStatus,
  createAccountId,
} from "@/lib/transfer-service/types";

const TRANSFER_SERVICE_URL = process.env.TRANSFER_SERVICE_URL ?? "http://localhost:3001";

// ── Client wrapper ──────────────────────────────────────────────────────────────

interface TBAccount {
  id: bigint;
  flags: number;
  ledger: number;
  code: number;
  timestamp: bigint;
  user_data_128: bigint;
  user_data_64: bigint;
  user_data_32: number;
  debits_pending: bigint;
  credits_pending: bigint;
  debits_posted: bigint;
  credits_posted: bigint;
  reserved: number;
}

interface TBCreateAccountResult {
  id: bigint;
  status: number;
}

interface TBTransfer {
  id: bigint;
  debit_account_id: bigint;
  credit_account_id: bigint;
  amount: bigint;
  pending_id: bigint;
  user_data_128: bigint;
  user_data_64: bigint;
  user_data_32: number;
  ledger: number;
  code: number;
  timestamp: bigint;
  reserved: number;
}

interface TBCreateTransferResult {
  id: bigint;
  status: number;
}

function toAccount(res: TBCreateAccountResponse): TBAccount {
  return {
    id: BigInt(res.id),
    flags: 0,
    ledger: res.ledger,
    code: res.code,
    timestamp: 0n,
    user_data_128: BigInt(res.user_data_128),
    user_data_64: BigInt(res.user_data_64),
    user_data_32: res.user_data_32,
    debits_pending: BigInt(res.debits_pending),
    credits_pending: BigInt(res.credits_pending),
    debits_posted: BigInt(res.debits_posted),
    credits_posted: BigInt(res.credits_posted),
    reserved: 0,
  };
}

function toTransfer(res: TBCreateTransferResponse): TBTransfer {
  return {
    id: BigInt(res.id),
    debit_account_id: BigInt(res.debit_account_id),
    credit_account_id: BigInt(res.credit_account_id),
    amount: BigInt(res.amount),
    pending_id: BigInt(res.pending_id),
    user_data_128: BigInt(res.user_data_128),
    user_data_64: BigInt(res.user_data_64),
    user_data_32: res.user_data_32,
    ledger: res.ledger,
    code: res.code,
    timestamp: 0n,
    reserved: 0,
  };
}

async function createAccountsNative(
  accounts: Array<{
    id: bigint;
    flags: number;
    ledger: number;
    code: number;
    timestamp: bigint;
    user_data_128: bigint;
    user_data_64: bigint;
    user_data_32: number;
    debits_pending: bigint;
    credits_pending: bigint;
    debits_posted: bigint;
    credits_posted: bigint;
    reserved: number;
  }>,
): Promise<TBCreateAccountResult[]> {
  const results: TBCreateAccountResult[] = [];

  for (const acct of accounts) {
    try {
      const res = await TransferServiceClient.createAccount({
        id: acct.id.toString(),
        ledger: acct.ledger,
        code: acct.code,
        user_data_128: acct.user_data_128.toString(),
        user_data_64: Number(acct.user_data_64),
        user_data_32: acct.user_data_32,
      });
      results.push({ id: BigInt(res.id), status: _CreateAccountStatus.ok });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      if (msg.includes("already exists")) {
        results.push({ id: acct.id, status: _CreateAccountStatus.id_already_exists });
      } else {
        results.push({ id: acct.id, status: _CreateAccountStatus.ok });
      }
    }
  }

  return results;
}

async function lookupAccountsNative(ids: bigint[]): Promise<TBAccount[]> {
  const accounts: TBAccount[] = [];

  for (const id of ids) {
    const res = await TransferServiceClient.getAccount(id.toString());
    if (res) {
      accounts.push(toAccount(res));
    }
  }

  return accounts;
}

async function createTransfersNative(
  transfers: Array<{
    id: bigint;
    debit_account_id: bigint;
    credit_account_id: bigint;
    amount: bigint;
    user_data_128: bigint;
    user_data_64: bigint;
    user_data_32: number;
    timeout: number;
    flags: number;
    pending_id: bigint;
    ledger: number;
    code: number;
    timestamp: bigint;
  }>,
): Promise<TBCreateTransferResult[]> {
  const results: TBCreateTransferResult[] = [];

  for (const t of transfers) {
    try {
      const res = await TransferServiceClient.createTransfer({
        id: t.id.toString(),
        debit_account_id: t.debit_account_id.toString(),
        credit_account_id: t.credit_account_id.toString(),
        amount: t.amount.toString(),
        ledger: t.ledger,
        code: t.code,
        user_data_128: t.user_data_128.toString(),
        user_data_64: Number(t.user_data_64),
        user_data_32: t.user_data_32,
        flags: t.flags,
      });
      results.push({ id: BigInt(res.id), status: _CreateTransferStatus.ok });
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      if (msg.includes("already exists")) {
        results.push({ id: t.id, status: _CreateTransferStatus.id_already_exists });
      } else if (msg.includes("Insufficient funds")) {
        results.push({ id: t.id, status: _CreateTransferStatus.overflows_debits_posted });
      } else {
        throw err;
      }
    }
  }

  return results;
}

// ── Client facade ───────────────────────────────────────────────────────────────

const nativeClient = {
  createAccounts: createAccountsNative,
  lookupAccounts: lookupAccountsNative,
  createTransfers: createTransfersNative,
};

let _clientReady = false;
let _clientError: string | null = null;

async function initClient() {
  try {
    const healthy = await TransferServiceClient.healthCheck();
    if (healthy) {
      _clientReady = true;
      console.log("[TigerBeetle] Transfer service connected");
    } else {
      _clientError = "Transfer service health check failed";
      console.warn("[TigerBeetle] Transfer service unreachable — operations will be skipped");
    }
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    _clientError = msg;
    console.warn(`[TigerBeetle] Failed to connect: ${msg}. Operations will be skipped.`);
  }
}

export const TBClient = {
  get ready() { return _clientReady; },
  get error() { return _clientError; },
  getClient: () => nativeClient,
  init: initClient,
};

// ── TB namespace (replaces tigerbeetle-node) ────────────────────────────────────

export const TB = {
  AccountFlags: _AccountFlags,
  CreateAccountStatus: _CreateAccountStatus,
  CreateTransferStatus: _CreateTransferStatus,
  id: createAccountId,
};

